use std::ptr;
use windows_sys::Win32::System::Threading::{OpenProcess, PROCESS_ALL_ACCESS};
use windows_sys::Win32::Foundation::HANDLE;

unsafe fn get_target_handle(pid: u32) -> HANDLE {
    // OpenProcess requests an access token to the target process ID.
    // PROCESS_ALL_ACCESS is extremely noisy and often flagged by EDRs,
    // but it gives us total control over the target's memory.
    let handle = OpenProcess(PROCESS_ALL_ACCESS, 0, pid);

    if handle == 0 {
        panic!("[-] Failed to obtain handle. Are you running as Admin?");
    }

    println!("[+] Got handle to PID: {}", pid);
    handle
}

