fn decrypt_payload(encrypted: &[u8], key: u8) -> Vec<u8> {
    // We use a basic XOR cipher to hide the payload from static analysis
    // In a real Trojan, use AES-256 or ChaCha20.
    let mut decrypted = Vec::with_capacity(encrypted.len());

    for byte in encrypted {
        // XOR decrypting the byte and pushing it to the new vector
        decrypted.push(byte ^ key);
    }

    println!("[*] Payload decrypted in memory.");
    decrypted
}

