use tokio::time::{sleep, Duration};

// We cannot run async code from a normal sync main function.
// The #[tokio::main] macro invisibly spins up the async engine for us.
#[tokio::main]
async fn main() {
    println!("[*] Sending network probe...");

    // Calling simulated_network_io() returns a Future, but does not run it.
    // We MUST use .await to drive it forward.
    let result = simulated_network_io().await;

    println!("[+] Probe complete: {}", result);
}

// We declare the function async so it can yield execution
async fn simulated_network_io() -> String {
    // tokio::time::sleep is non-blocking. It lets the thread do other work.
    sleep(Duration::from_secs(2)).await;
    String::from("ACK")
}

